import functools
from typing import ForwardRef, Any
from fastapi.dependencies.utils import get_typed_signature
import inspect

# Simulate module_a
class MyModel:
    pass

def my_endpoint(a: "MyModel"):
    return {"a": a}

# Simulate module_b
def wrapper(func):
    @functools.wraps(func)
    def wrapped(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapped

wrapped_endpoint = wrapper(my_endpoint)

print(f"Wrapped endpoint globals: {wrapped_endpoint.__globals__ is my_endpoint.__globals__}")
# In this script, they are the same because everything is in the same module.
# To truly simulate different modules, we'd need different files.

try:
    sig = get_typed_signature(wrapped_endpoint)
    print("Success!")
    print(sig)
except Exception as e:
    print(f"Failed: {e}")
    import traceback
    traceback.print_exc()

